+    cwd: workDir,
+    env: { ...process.env, ...GIT_ENV },
+    stdio: "pipe",
+  });
+  execSync("git push origin main", {
+    cwd: workDir,
+    env: { ...process.env, ...GIT_ENV },
+    stdio: "pipe",
+  });
+
+  return `file://${bareDir}`;
+}
+
+// ── Stub builders ─────────────────────────────────────────────────────────────
+
+/**
+ * Create a stub `hermes` binary.
+ *
+ * "normal" mode:
+ *   - Writes a file to cwd (TASK_REPO_PATH) so Phase 6 has changes to commit.
+ *   - Pre-writes a valid in_review result.json to RESULT_PATH so Layer 1 recovery
+ *     short-circuits after Phase 6's openImplPR fails (file:// URL can't be parsed
+ *     as GitHub coords). This verifies the recovery short-circuit path.
+ *
+ * "sigkill" mode:
+ *   - Writes a file first (so Phase 6 commits something), then self-kills via SIGKILL.
+ *   - No result.json is written, so recovery detects the abnormal exit.
+ *
+ * Returns the directory containing the stub (add to PATH).
+ */
+function makeHermesStub(mode: "normal" | "sigkill", prUrl?: string): string {
+  const stubDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-stub-")));
+
+  const scriptContent =
+    mode === "sigkill"
+      ? [
+          "#!/usr/bin/env node",
+          `const fs = require("node:fs");`,
+          // Write a file so Phase 6 has changes to commit.
+          `fs.writeFileSync("sigkill-output.txt", "written before kill\\n", "utf-8");`,
+          // Self-kill with SIGKILL to simulate abnormal termination.
+          `process.kill(process.pid, "SIGKILL");`,
+        ].join("\n")
+      : [
+          "#!/usr/bin/env node",
+          `const fs = require("node:fs");`,
+          `const path = require("node:path");`,
+          // Write a file so Phase 6 has changes to commit and push.
+          `fs.writeFileSync("hermes-output.txt", "hermes was here\\n", "utf-8");`,
+          // Pre-write a valid in_review result.json so recovery short-circuits
+          // after Phase 6's openImplPR fails for the file:// URL.
+          `const resultPath = process.env.RESULT_PATH;`,
+          `if (resultPath) {`,
+          `  fs.mkdirSync(path.dirname(resultPath), { recursive: true });`,
+          `  fs.writeFileSync(resultPath, JSON.stringify({`,
+          `    terminal_status: "in_review",`,
+          `    pr_url: ${JSON.stringify(prUrl ?? "https://github.com/stub-org/stub-repo/pull/1")}`,
+          `  }), "utf-8");`,
+          `}`,
+          `process.exit(0);`,
+        ].join("\n");
+
+  const stubPath = join(stubDir, "hermes");
+  writeFileSync(stubPath, scriptContent, "utf-8");
+  chmodSync(stubPath, 0o755);
+  return stubDir;
+}
+
+// ── Synchronous executor runner ───────────────────────────────────────────────
+
+interface HermesRunOpts {
+  hermesStubMode: "normal" | "sigkill";
+  mgmtRepoUrl: string;
+  implRepoUrl: string;
+  taskId?: string;
+  featureId?: string;
+  prUrl?: string;
+}
+
+function buildEnv(opts: HermesRunOpts & { resultPath: string; executorWorkdir: string; hermesStubDir: string }): NodeJS.ProcessEnv {
+  const {
+    mgmtRepoUrl,
+    implRepoUrl,
+    taskId = "T1",
+    featureId = "hermes-test-feature",
+    resultPath,
+    executorWorkdir,
+    hermesStubDir,
+  } = opts;
+
+  const taskBranch = `feature/${featureId}-${taskId}`;
+
+  return {
+    ...process.env,
+    PATH: `${hermesStubDir}:${process.env.PATH ?? "/usr/bin:/bin"}`,
+    TASK_ID: taskId,
+    FEATURE_ID: featureId,
+    WORKSPACE_ID: "hermes-integration-test",
+    TASK_REPO_URL: implRepoUrl,
+    TASK_REPO_BRANCH: taskBranch,
+    TASK_BASE_BRANCH: "main",
+    EXECUTOR_WORKDIR: executorWorkdir,
+    MGMT_REPO_URL: mgmtRepoUrl,
+    RESULT_PATH: resultPath,
+    GITHUB_TOKEN: "",
+    HERMES_INFERENCE_MODEL: "stub-model",
+    HERMES_INFERENCE_PROVIDER: "stub-provider",
+    HERMES_MAX_TURNS: "10",
+    GIT_AUTHOR_NAME: "Integration Test",
+    GIT_AUTHOR_EMAIL: "test@example.com",
+    GIT_COMMITTER_NAME: "Integration Test",
+    GIT_COMMITTER_EMAIL: "test@example.com",
+    CLAUDE_AGENT_RUNTIME: "1",
+  };
+}
+
+function runHermesSync(opts: HermesRunOpts): {
+  exitCode: number | null;
+  result: Record<string, unknown> | null;
+  executorWorkdir: string;
+} {
+  const resultDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-result-")));
+  const resultPath = join(resultDir, "result.json");
+  const executorWorkdir = trackDir(mkdtempSync(join(tmpdir(), "hermes-workdir-")));
+  const hermesStubDir = makeHermesStub(opts.hermesStubMode, opts.prUrl);
+
+  const env = buildEnv({ ...opts, resultPath, executorWorkdir, hermesStubDir });
+
+  const proc = spawnSync("node", [HERMES_EXECUTOR_BIN], {
+    env,
+    encoding: "utf-8",
+    timeout: 90_000,
+  });
+
+  let result: Record<string, unknown> | null = null;
+  if (existsSync(resultPath)) {
+    try {
+      result = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
+    } catch { /* ignore */ }
+  }
+
+  return { exitCode: proc.status, result, executorWorkdir };
+}
+
+// ── Async executor runner (for parallel test) ─────────────────────────────────
+
+function runHermesAsync(opts: HermesRunOpts): Promise<{
+  exitCode: number | null;
+  result: Record<string, unknown> | null;
+}> {
+  return new Promise((resolve) => {
+    const resultDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-result-")));
+    const resultPath = join(resultDir, "result.json");
+    const executorWorkdir = trackDir(mkdtempSync(join(tmpdir(), "hermes-workdir-")));
+    const hermesStubDir = makeHermesStub(opts.hermesStubMode, opts.prUrl);
+
+    const env = buildEnv({ ...opts, resultPath, executorWorkdir, hermesStubDir });
+
+    const child = spawn("node", [HERMES_EXECUTOR_BIN], { env, stdio: "pipe" });
+
+    child.on("close", (code) => {
+      let result: Record<string, unknown> | null = null;
+      if (existsSync(resultPath)) {
+        try {
+          result = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
+        } catch { /* ignore */ }
+      }
+      resolve({ exitCode: code, result });
+    });
+
+    child.on("error", () => {
+      resolve({ exitCode: null, result: null });
+    });
+  });
+}
+
+// ── Tests ─────────────────────────────────────────────────────────────────────
+
+/**
+ * Happy path: hermes exits 0, writes file changes + pre-writes in_review result.json.
+ *
+ * Phase 6 commits+pushes the file change, then openImplPR fails (file:// URL).
+ * Recovery short-circuits because the stub pre-wrote a valid in_review result.json.
+ * Verifies that the executor correctly short-circuits recovery on valid prior results.
+ */
+describe("Hermes executor — happy path (normal exit)", () => {
+  it("writes result.json with terminal_status: in_review after successful hermes run", () => {
+    const mgmtRepoUrl = makeMinimalBareMgmtRepo("T1", "hermes-test-feature");
+    const implRepoUrl = makeMinimalBareImplRepo();
+    const prUrl = "https://github.com/stub-org/stub-repo/pull/1";
+
+    const { exitCode, result } = runHermesSync({
+      hermesStubMode: "normal",
+      mgmtRepoUrl,
+      implRepoUrl,
+      taskId: "T1",
+      featureId: "hermes-test-feature",
+      prUrl,
+    });
+
+    expect(exitCode).toBe(0);
+    expect(result).not.toBeNull();
+    expect(result?.terminal_status).toBe("in_review");
+    expect(result?.pr_url).toBe(prUrl);
+  }, 90_000);
+});
+
+/**
+ * Abnormal exit (SIGKILL): stub hermes writes a file then kills itself.
+ *
+ * Phase 6 commits+pushes the file, then openImplPR fails (file:// URL).
+ * No result.json was pre-written. Recovery detects SIGKILL and writes blocked result.
+ */
+describe("Hermes executor — abnormal exit (SIGKILL recovery)", () => {
+  it("produces a blocked result.json with executor_signal_SIGKILL when hermes is killed", () => {
+    const mgmtRepoUrl = makeMinimalBareMgmtRepo("T2", "hermes-test-sigkill");
+    const implRepoUrl = makeMinimalBareImplRepo();
+
+    const { exitCode, result } = runHermesSync({
+      hermesStubMode: "sigkill",
+      mgmtRepoUrl,
+      implRepoUrl,
+      taskId: "T2",
+      featureId: "hermes-test-sigkill",
+    });
+
+    expect(exitCode).toBe(0);
+    expect(result).not.toBeNull();
+    expect(result?.terminal_status).toBe("blocked");
+    expect(result?.blocked_reason).toBe("executor_signal_SIGKILL");
+  }, 90_000);
+});
+
+/**
+ * Parallel isolation: two executor instances each use their own EXECUTOR_WORKDIR.
+ *
+ * Both run concurrently. Each has its own HERMES_HOME, impl dir, and mgmt dir.
+ * Verifies that concurrent runs do not cause HERMES_HOME or git working dir conflicts.
+ */
+describe("Hermes executor — parallel task isolation", () => {
+  it("two concurrent executor instances complete without conflicts", async () => {
+    const mgmtRepoUrl1 = makeMinimalBareMgmtRepo("T3", "hermes-parallel-a");
+    const implRepoUrl1 = makeMinimalBareImplRepo();
+
+    const mgmtRepoUrl2 = makeMinimalBareMgmtRepo("T4", "hermes-parallel-b");
+    const implRepoUrl2 = makeMinimalBareImplRepo();
+
+    const prUrl1 = "https://github.com/stub-org/stub-repo/pull/1";
+    const prUrl2 = "https://github.com/stub-org/stub-repo/pull/2";
+
+    // Launch both executors truly in parallel via async spawn.
+    const [inst1, inst2] = await Promise.all([
+      runHermesAsync({
+        hermesStubMode: "normal",
+        mgmtRepoUrl: mgmtRepoUrl1,
+        implRepoUrl: implRepoUrl1,
+        taskId: "T3",
+        featureId: "hermes-parallel-a",
+        prUrl: prUrl1,
+      }),
+      runHermesAsync({
+        hermesStubMode: "normal",
+        mgmtRepoUrl: mgmtRepoUrl2,
+        implRepoUrl: implRepoUrl2,
+        taskId: "T4",
+        featureId: "hermes-parallel-b",
+        prUrl: prUrl2,
+      }),
+    ]);
+
+    // Both instances must exit cleanly.
+    expect(inst1.exitCode).toBe(0);
+    expect(inst2.exitCode).toBe(0);
+
+    // Both must produce in_review results (stub pre-wrote valid result.json).
+    expect(inst1.result?.terminal_status).toBe("in_review");
+    expect(inst2.result?.terminal_status).toBe("in_review");
+
+    // Each result must reference its own PR URL — no cross-contamination.
+    expect(inst1.result?.pr_url).toBe(prUrl1);
+    expect(inst2.result?.pr_url).toBe(prUrl2);
+  }, 180_000);
+});
